import { readdir, readFile, realpath, stat } from 'node:fs/promises';
import path from 'node:path';
import { canonicalSha256 } from '../../core/canonical-json.mjs';
import { canonicalTextContent } from '../../core/canonical-text.mjs';
const ordered=['overview','procedure','decision-tables','verification','failure-modes','examples'];
const idFor=(relative)=>relative==='SKILL.md'?'overview':path.basename(relative,path.extname(relative));
async function files(root){const out=[];try{await stat(path.join(root,'SKILL.md'));out.push('SKILL.md');}catch{}try{for(const name of await readdir(path.join(root,'sections')))if(name.endsWith('.md'))out.push(`sections/${name}`);}catch{}return out.sort((a,b)=>ordered.indexOf(idFor(a))-ordered.indexOf(idFor(b))||a.localeCompare(b));}
async function safePath(root,relative){if(path.isAbsolute(relative)||relative.replaceAll('\\','/').split('/').includes('..'))throw new Error(`Unsafe section path: ${relative}`);const [rr,fr]=await Promise.all([realpath(root),realpath(path.join(root,relative))]);if(fr!==rr&&!fr.startsWith(`${rr}${path.sep}`))throw new Error(`Skill section escapes package root: ${relative}`);return fr;}
export async function buildSectionIndex(root,{registry,models=['gpt-5.6','claude-opus-4.2','gemini-3.0-pro','qwen3.5-32b']}={}){if(!registry)throw new TypeError('TokenAccountingRegistry is required');const sections=[];for(const relative of await files(root)){const absolute=await safePath(root,relative);const content=canonicalTextContent(await readFile(absolute,'utf8'));const tokens={};for(const model of models)tokens[model]=await registry.countText(model,content);sections.push(Object.freeze({id:idFor(relative),path:relative,sha256:canonicalSha256(content),bytes:Buffer.byteLength(content),tokens:Object.freeze(tokens)}));}return Object.freeze({schemaVersion:1,generatedAt:null,sections:Object.freeze(sections),indexSha256:canonicalSha256(sections)});}
export async function loadSkillSections(root,index,{sectionIds,model='gpt-5.6',hardTokens,registry}={}){if(!registry)throw new TypeError('TokenAccountingRegistry is required');if(!Array.isArray(sectionIds)||!sectionIds.length)throw new TypeError('sectionIds are required');const byId=new Map(index.sections.map((section)=>[section.id,section]));const loaded=[];let tokens=0;for(const id of sectionIds){const section=byId.get(id);if(!section)throw new Error(`Unknown skill section: ${id}`);const absolute=await safePath(root,section.path);const content=canonicalTextContent(await readFile(absolute,'utf8'));if(canonicalSha256(content)!==section.sha256)throw new Error(`Skill section digest mismatch: ${id}`);const count=section.tokens?.[model]??await registry.countText(model,content);if(tokens+count>hardTokens)throw new RangeError(`Skill section token budget exceeded: ${tokens+count} > ${hardTokens}`);tokens+=count;loaded.push(Object.freeze({...section,content,tokens:count}));}return Object.freeze({sections:Object.freeze(loaded),tokens,text:loaded.map((section)=>section.content).join('\n\n'),omitted:index.sections.filter((section)=>!sectionIds.includes(section.id)).map((section)=>({id:section.id,reason:'not selected by route plan'}))});}
